window.BOOK={"key":"tahawiyya","app":"mutoon","lsk":"mutoon_tahawiyya_v1","title":"العقيدة الطحاوية","unitWord":"فقرة","sub":"العقيدة · أبو جعفر الطحاوي الحنفي (ت ٣٢١هـ) · ٢٠ بابًا","source":"https://shamela.ws/book/9568 (العقيدة الطحاوية، شرح وتعليق الألباني، المكتب الإسلامي ط2 1414هـ: اللفظ وترقيم الفقرات 1-105) + الشكل من https://shamela.ws/book/8352 (المتن في شرح ابن أبي العز، ط الرسالة، تحقيق التركي والأرنؤوط) ثم https://shamela.ws/book/574/121 (نشرة د. عبد المحسن القاسم المشكولة) · قوبل بـ: word-by-word script collation of al-Albani, Ibn Abi al-Izz (Risala) and al-Qasim; Arabic Wikisource seen - see tahawiyya-sources.md","note":"اللفظ المتداول كما في نشرة الألباني الموافقة لمتن ابن أبي العز، على ترقيمها ١٠٥ فقرات. والشكل منقول كلمةً كلمةً من المتن المشكول في شرح ابن أبي العز (ط الرسالة)، ثم من نشرة د. عبد المحسن القاسم، وما بقي كُمِّل وسُجّل. عناوين الأبواب تقسيم وصفي للتطبيق.","chapters":[{"id":"ta1","title":"مقدمة المتن","units":[{"id":"ta1_1","label":"مقدمة المتن · ١","segs":[["matn","الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ. قَالَ الْعَلَّامَةُ حُجَّةُ الْإِسْلَامِ أَبُو جَعْفَرٍ الْوَرَّاقُ الطَّحَاوِيُّ بِمِصْرَ رَحِمَهُ اللَّهُ: هَذَا ذِكْرُ بَيَانِ عَقِيدَةِ أَهْلِ السُّنَّةِ وَالْجَمَاعَةِ عَلَى مَذْهَبِ فُقَهَاءِ الْمِلَّةِ:"]]},{"id":"ta1_2","label":"مقدمة المتن · ٢","segs":[["matn","أَبِي حَنِيفَةَ النُّعْمَانِ بْنِ ثَابِتٍ الْكُوفِيِّ، وَأَبِي يُوسُفَ يَعْقُوبَ بْنِ إِبْرَاهِيمَ الْأَنْصَارِيِّ، وَأَبِي عَبْدِ اللَّهِ مُحَمَّدِ بْنِ الْحَسَنِ الشَّيْبَانِيِّ، رِضْوَانُ اللَّهِ عَلَيْهِمْ أَجْمَعِينَ، وَمَا يَعْتَقِدُونَ مِنْ أُصُولِ الدِّينِ، وَيَدِينُونَ بِهِ رَبَّ الْعَالَمِينَ."]]}]},{"id":"ta2","title":"التوحيد وصفات الله","units":[{"id":"ta2_1","label":"التوحيد وصفات الله · ١","segs":[["matn","نَقُولُ فِي تَوْحِيدِ اللَّهِ مُعْتَقِدِينَ بِتَوْفِيقِ اللَّهِ: إِنَّ اللَّهَ وَاحِدٌ لَا شَرِيكَ لَهُ."]]},{"id":"ta2_2","label":"التوحيد وصفات الله · ٢","segs":[["matn","وَلَا شَيْءَ مِثْلُهُ. وَلَا شَيْءَ يُعْجِزُهُ."]]},{"id":"ta2_3","label":"التوحيد وصفات الله · ٣","segs":[["matn","وَلَا إِلَهَ غَيْرُهُ. قَدِيمٌ بِلَا ابْتِدَاءٍ دَائِمٌ بِلَا انْتِهَاءٍ."]]},{"id":"ta2_4","label":"التوحيد وصفات الله · ٤","segs":[["matn","لَا يَفْنَى وَلَا يَبِيدُ. وَلَا يَكُونُ إِلَّا مَا يُرِيدُ."]]},{"id":"ta2_5","label":"التوحيد وصفات الله · ٥","segs":[["matn","لَا تَبْلُغُهُ الْأَوْهَامُ، وَلَا تُدْرِكُهُ الْأَفْهَامُ."]]},{"id":"ta2_6","label":"التوحيد وصفات الله · ٦","segs":[["matn","وَلَا يُشْبِهُ الْأَنَامَ. حَيٌّ لَا يَمُوتُ قَيُّومٌ لَا يَنَامُ."]]},{"id":"ta2_7","label":"التوحيد وصفات الله · ٧","segs":[["matn","خَالِقٌ بِلَا حَاجَةٍ، رَازِقٌ بِلَا مُؤْنَةٍ."]]},{"id":"ta2_8","label":"التوحيد وصفات الله · ٨","segs":[["matn","مُمِيتٌ بِلَا مَخَافَةٍ، بَاعِثٌ بِلَا مَشَقَّةٍ."]]},{"id":"ta2_9","label":"التوحيد وصفات الله · ٩","segs":[["matn","مَا زَالَ بِصِفَاتِهِ قَدِيمًا قَبْلَ خَلْقِهِ، لَمْ يَزْدَدْ بِكَوْنِهِمْ شَيْئًا لَمْ يَكُنْ قَبْلَهُمْ مِنْ صِفَتِهِ، وَكَمَا كَانَ بِصِفَاتِهِ أَزَلِيًّا، كَذَلِكَ لَا يَزَالُ عَلَيْهَا أَبَدِيًّا."]]},{"id":"ta2_10","label":"التوحيد وصفات الله · ١٠","segs":[["matn","لَيْسَ بَعْدَ خَلَقَ الْخَلْقَ اسْتَفَادَ اسْمَ الْخَالِقِ وَلَا بِإِحْدَاثِهِ الْبَرِيَّةَ اسْتَفَادَ اسْمَ الْبَارِي."]]},{"id":"ta2_11","label":"التوحيد وصفات الله · ١١","segs":[["matn","لَهُ مَعْنَى الرُّبُوبِيَّةِ وَلَا مَرْبُوبَ، وَمَعْنَى الْخَالِقِ وَلَا مَخْلُوقَ."]]},{"id":"ta2_12","label":"التوحيد وصفات الله · ١٢","segs":[["matn","وَكَمَا أَنَّهُ مُحْيِي الْمَوْتَى بَعْدَمَا أَحْيَا اسْتَحَقَّ هَذَا الِاسْمَ قَبْلَ إِحْيَائِهِمْ، كَذَلِكَ اسْتَحَقَّ اسْمَ الْخَالِقِ قَبْلَ إِنْشَائِهِمْ."]]},{"id":"ta2_13","label":"التوحيد وصفات الله · ١٣","segs":[["matn","ذَلِكَ بِأَنَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، وَكُلُّ شَيْءٍ إِلَيْهِ فَقِيرٌ، وَكُلُّ أَمْرٍ عَلَيْهِ يَسِيرٌ، لَا يَحْتَاجُ إِلَى شَيْءٍ ﴿لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ﴾."]]}]},{"id":"ta3","title":"الخلق والمشيئة","units":[{"id":"ta3_1","label":"الخلق والمشيئة · ١","segs":[["matn","خَلَقَ الْخَلْقَ بِعِلْمِهِ. وَقَدَّرَ لَهُمْ أَقْدَارًا."]]},{"id":"ta3_2","label":"الخلق والمشيئة · ٢","segs":[["matn","وَضَرَبَ لَهُمْ آجَالًا. وَلَمْ يَخْفَ عَلَيْهِ شَيْءٌ قَبْلَ أَنْ يَخْلُقَهُمْ، وَعَلِمَ مَا هُمْ عَامِلُونَ قَبْلَ أَنْ يَخْلُقَهُمْ."]]},{"id":"ta3_3","label":"الخلق والمشيئة · ٣","segs":[["matn","وَأَمَرَهُمْ بِطَاعَتِهِ، وَنَهَاهُمْ عَنْ مَعْصِيَتِهِ. وَكُلُّ شَيْءٍ يَجْرِي بِتَقْدِيرِهِ وَمَشِيئَتِهِ، وَمَشِيئَتُهُ تَنْفُذُ، لَا مَشِيئَةَ لِلْعِبَادِ، إِلَّا مَا شَاءَ لَهُمْ، فَمَا شَاءَ لَهُمْ كَانَ، وَمَا لَمْ يَشَأْ لَمْ يَكُنْ."]]},{"id":"ta3_4","label":"الخلق والمشيئة · ٤","segs":[["matn","يَهْدِي مَنْ يَشَاءُ وَيَعْصِمُ وَيُعَافِي فَضْلًا. وَيُضِلُّ مَنْ يَشَاءُ وَيَخْذُلُ وَيَبْتَلِي عَدْلًا."]]},{"id":"ta3_5","label":"الخلق والمشيئة · ٥","segs":[["matn","وَكُلُّهُمْ يَتَقَلَّبُونَ فِي مَشِيئَتِهِ، بَيْنَ فَضْلِهِ وَعَدْلِهِ."]]},{"id":"ta3_6","label":"الخلق والمشيئة · ٦","segs":[["matn","وَهُوَ مُتَعَالٍ عَنِ الْأَضْدَادِ وَالْأَنْدَادِ. لَا رَادَّ لِقَضَائِهِ، وَلَا مُعَقِّبَ لِحُكْمِهِ، وَلَا غَالِبَ لِأَمْرِهِ."]]},{"id":"ta3_7","label":"الخلق والمشيئة · ٧","segs":[["matn","آمَنَّا بِذَلِكَ كُلِّهِ، وَأَيْقَنَّا أَنَّ كُلًّا مِنْ عِنْدِهِ."]]}]},{"id":"ta4","title":"النبي صلى الله عليه وسلم","units":[{"id":"ta4_1","label":"النبي صلى الله عليه وسلم · ١","segs":[["matn","وَإِنَّ مُحَمَّدًا عَبْدُهُ الْمُصْطَفَى، وَنَبِيُّهُ الْمُجْتَبَى، وَرَسُولُهُ الْمُرْتَضَى."]]},{"id":"ta4_2","label":"النبي صلى الله عليه وسلم · ٢","segs":[["matn","وَأَنَّهُ خَاتَمُ الْأَنْبِيَاءِ وَإِمَامُ الْأَتْقِيَاءِ وَسَيِّدُ الْمُرْسَلِينَ وَحَبِيبُ رَبِّ الْعَالَمِينَ."]]},{"id":"ta4_3","label":"النبي صلى الله عليه وسلم · ٣","segs":[["matn","وَكُلُّ دَعْوَى النُّبُوَّةِ بَعْدَهُ فَغَيٌّ وَهَوًى."]]},{"id":"ta4_4","label":"النبي صلى الله عليه وسلم · ٤","segs":[["matn","وَهُوَ الْمَبْعُوثُ إِلَى عَامَّةِ الْجِنِّ وَكَافَّةِ الْوَرَى، بِالْحَقِّ وَالْهُدَى، وَبِالنُّورِ وَالضِّيَاءِ."]]}]},{"id":"ta5","title":"القرآن كلام الله","units":[{"id":"ta5_1","label":"القرآن كلام الله · ١","segs":[["matn","وَإِنَّ الْقُرْآنَ كَلَامُ اللَّهِ، مِنْهُ بَدَا بِلَا كَيْفِيَّةٍ قَوْلًا، وَأَنْزَلَهُ عَلَى رَسُولِهِ وَحْيًا، وَصَدَّقَهُ الْمُؤْمِنُونَ عَلَى ذَلِكَ حَقًّا، وَأَيْقَنُوا أَنَّهُ كَلَامُ اللَّهِ تَعَالَى بِالْحَقِيقَةِ، لَيْسَ بِمَخْلُوقٍ كَكَلَامِ الْبَرِيَّةِ."]]},{"id":"ta5_2","label":"القرآن كلام الله · ٢","segs":[["matn","فَمَنْ سَمِعَهُ فَزَعَمَ أَنَّهُ كَلَامُ الْبَشَرِ فَقَدْ كَفَرَ، وَقَدْ ذَمَّهُ اللَّهُ وَعَابَهُ وَأَوْعَدَهُ بِسَقَرَ حَيْثُ قَالَ تَعَالَى: ﴿سَأُصْلِيهِ سَقَرَ﴾ فَلَمَّا أَوْعَدَ اللَّهُ بِسَقَرَ لِمَنْ قَالَ:"]]},{"id":"ta5_3","label":"القرآن كلام الله · ٣","segs":[["matn","﴿إِنْ هَذَا إِلَّا قَوْلُ الْبَشَرِ﴾ عَلِمْنَا وَأَيْقَنَّا أَنَّهُ قَوْلُ خَالِقِ الْبَشَرِ، وَلَا يُشْبِهُ قَوْلَ الْبَشَرِ."]]},{"id":"ta5_4","label":"القرآن كلام الله · ٤","segs":[["matn","وَمَنْ وَصَفَ اللَّهَ بِمَعْنًى مِنْ مَعَانِي الْبَشَرِ، فَقَدْ كَفَرَ فَمَنْ أَبْصَرَ هَذَا اعْتَبَرَ. وَعَنْ مِثْلِ قَوْلِ الْكُفَّارِ انْزَجَرَ. وَعَلِمَ أَنَّهُ بِصِفَاتِهِ لَيْسَ كَالْبَشَرِ."]]}]},{"id":"ta6","title":"الرؤية والتسليم والتنزيه","units":[{"id":"ta6_1","label":"الرؤية والتسليم والتنزيه · ١","segs":[["matn","وَالرُّؤْيَةُ حَقٌّ لِأَهْلِ الْجَنَّةِ، بِغَيْرِ إِحَاطَةٍ وَلَا كَيْفِيَّةٍ، كَمَا نَطَقَ بِهِ كِتَابُ رَبِّنَا: ﴿وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ إِلَى رَبِّهَا نَاظِرَةٌ﴾ وَتَفْسِيرُهُ عَلَى مَا أَرَادَهُ اللَّهُ تَعَالَى وَعَلِمَهُ،"]]},{"id":"ta6_2","label":"الرؤية والتسليم والتنزيه · ٢","segs":[["matn","وَكُلُّ مَا جَاءَ فِي ذَلِكَ مِنَ الْحَدِيثِ الصَّحِيحِ عَنِ الرَّسُولِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَهُوَ كَمَا قَالَ، وَمَعْنَاهُ عَلَى مَا أَرَادَ، لَا نَدْخُلُ فِي ذَلِكَ مُتَأَوِّلِينَ بِآرَائِنَا وَلَا مُتَوَهِّمِينَ بِأَهْوَائِنَا،"]]},{"id":"ta6_3","label":"الرؤية والتسليم والتنزيه · ٣","segs":[["matn","فَإِنَّهُ مَا سَلِمَ فِي دِينِهِ إِلَّا مَنْ سَلَّمَ لِلَّهِ عَزَّ وَجَلَّ وَلِرَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَرَدَّ عِلْمَ مَا اشْتَبَهَ عَلَيْهِ إِلَى عَالِمِهِ."]]},{"id":"ta6_4","label":"الرؤية والتسليم والتنزيه · ٤","segs":[["matn","وَلَا تَثْبُتُ قَدَمُ الْإِسْلَامِ إِلَّا عَلَى ظَهْرِ التَّسْلِيمِ وَالِاسْتِسْلَامِ فَمَنْ رَامَ عِلْمَ مَا حُظِرَ عَنْهُ عِلْمُهُ، وَلَمْ يَقْنَعْ بِالتَّسْلِيمِ فَهْمُهُ، حَجَبَهُ مَرَامُهُ عَنْ خَالِصِ التَّوْحِيدِ، وَصَافِي الْمَعْرِفَةِ،"]]},{"id":"ta6_5","label":"الرؤية والتسليم والتنزيه · ٥","segs":[["matn","وَصَحِيحِ الْإِيمَانِ فَيَتَذَبْذَبُ بَيْنَ الْكُفْرِ وَالْإِيمَانِ، وَالتَّصْدِيقِ وَالتَّكْذِيبِ، وَالْإِقْرَارِ وَالْإِنْكَارِ، مُوَسْوِسًا تَائِهًا، شَاكًّا زَائِغًا، لَا مُؤْمِنًا مُصَدِّقًا، وَلَا جَاحِدًا مُكَذِّبًا."]]},{"id":"ta6_6","label":"الرؤية والتسليم والتنزيه · ٦","segs":[["matn","وَلَا يَصِحُّ الْإِيمَانُ بِالرُّؤْيَةِ لِأَهْلِ دَارِ السَّلَامِ لِمَنِ اعْتَبَرَهَا مِنْهُمْ بِوَهْمٍ، أَوْ تَأَوَّلَهَا بِفَهْمٍ، إِذْ كَانَ تَأْوِيلُ الرُّؤْيَةِ وَتَأْوِيلُ كُلِّ مَعْنًى يُضَافُ إِلَى الرُّبُوبِيَّةِ بِتَرْكِ التَّأْوِيلِ وَلُزُومِ التَّسْلِيمِ،"]]},{"id":"ta6_7","label":"الرؤية والتسليم والتنزيه · ٧","segs":[["matn","وَعَلَيْهِ دِينُ الْمُسْلِمِينَ، وَمَنْ لَمْ يَتَوَقَّ النَّفْيَ وَالتَّشْبِيهَ، زَلَّ وَلَمْ يُصِبِ التَّنْزِيهَ فَإِنَّ رَبَّنَا جَلَّ وَعَلَا مَوْصُوفٌ بِصِفَاتِ الْوَحْدَانِيَّةِ، مَنْعُوتٌ بِنُعُوتِ الْفَرْدَانِيَّةِ، لَيْسَ فِي مَعْنَاهُ أَحَدٌ مِنَ الْبَرِيَّةِ."]]},{"id":"ta6_8","label":"الرؤية والتسليم والتنزيه · ٨","segs":[["matn","وَتَعَالَى عَنِ الْحُدُودِ وَالْغَايَاتِ، وَالْأَرْكَانِ وَالْأَعْضَاءِ وَالْأَدَوَاتِ، لَا تَحْوِيهِ الْجِهَاتُ السِّتُّ كَسَائِرِ الْمُبْتَدَعَاتِ."]]}]},{"id":"ta7","title":"المعراج والحوض والشفاعة والميثاق","units":[{"id":"ta7_1","label":"المعراج والحوض والشفاعة والميثاق · ١","segs":[["matn","وَالْمِعْرَاجُ حَقٌّ، وَقَدْ أُسْرِيَ بِالنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعُرِجَ بِشَخْصِهِ فِي الْيَقَظَةِ، إِلَى السَّمَاءِ ثُمَّ إِلَى حَيْثُ شَاءَ اللَّهُ مِنَ الْعُلَا وَأَكْرَمَهُ اللَّهُ بِمَا شَاءَ وَأَوْحَى إِلَيْهِ مَا أَوْحَى، ﴿مَا كَذَبَ الْفُؤَادُ مَا رَأَى﴾ فَصَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْآخِرَةِ وَالْأُولَى."]]},{"id":"ta7_2","label":"المعراج والحوض والشفاعة والميثاق · ٢","segs":[["matn","وَالْحَوْضُ الَّذِي أَكْرَمَهُ اللَّهُ تَعَالَى بِهِ غِيَاثًا لِأُمَّتِهِ حَقٌّ."]]},{"id":"ta7_3","label":"المعراج والحوض والشفاعة والميثاق · ٣","segs":[["matn","وَالشَّفَاعَةُ الَّتِي ادَّخَرَهَا لَهُمْ حَقٌّ، كَمَا رُوِيَ فِي الْأَخْبَارِ."]]},{"id":"ta7_4","label":"المعراج والحوض والشفاعة والميثاق · ٤","segs":[["matn","وَالْمِيثَاقُ الَّذِي أَخَذَهُ اللَّهُ تَعَالَى مِنْ آدَمَ وَذُرِّيَّتِهِ حَقٌّ."]]}]},{"id":"ta8","title":"القدر","units":[{"id":"ta8_1","label":"القدر · ١","segs":[["matn","وَقَدْ عَلِمَ اللَّهُ تَعَالَى فِيمَا لَمْ يَزَلْ عَدَدَ مَنْ يَدْخُلُ الْجَنَّةَ، وَعَدَدَ مَنْ يَدْخُلُ النَّارَ، جُمْلَةً وَاحِدَةً، فَلَا يُزَادُ فِي ذَلِكَ الْعَدَدِ وَلَا يُنْقَصُ مِنْهُ."]]},{"id":"ta8_2","label":"القدر · ٢","segs":[["matn","وَكَذَلِكَ أَفْعَالُهُمْ فِيمَا عَلِمَ مِنْهُمْ أَنْ يَفْعَلُوهُ وَكُلٌّ مُيَسَّرٌ لِمَا خُلِقَ لَهُ، وَالْأَعْمَالُ بِالْخَوَاتِيمِ، وَالسَّعِيدُ مَنْ سَعِدَ بِقَضَاءِ اللَّهِ، وَالشَّقِيُّ مَنْ شَقِيَ بِقَضَاءِ اللَّهِ."]]},{"id":"ta8_3","label":"القدر · ٣","segs":[["matn","وَأَصْلُ الْقَدَرِ سِرُّ اللَّهِ تَعَالَى فِي خَلْقِهِ، لَمْ يَطَّلِعْ عَلَى ذَلِكَ مَلَكٌ مُقَرَّبٌ، وَلَا نَبِيٌّ مُرْسَلٌ، وَالتَّعَمُّقُ وَالنَّظَرُ فِي ذَلِكَ ذَرِيعَةُ الْخِذْلَانِ، وَسُلَّمُ الْحِرْمَانِ، وَدَرَجَةُ الطُّغْيَانِ،"]]},{"id":"ta8_4","label":"القدر · ٤","segs":[["matn","فَالْحَذَرَ كُلَّ الْحَذَرِ مِنْ ذَلِكَ نَظَرًا وَفِكْرًا وَوَسْوَسَةً، فَإِنَّ اللَّهَ تَعَالَى طَوَى عِلْمَ الْقَدَرِ عَنْ أَنَامِهِ، وَنَهَاهُمْ عَنْ مَرَامِهِ، كَمَا قَالَ اللَّهُ تَعَالَى فِي كِتَابِهِ:"]]},{"id":"ta8_5","label":"القدر · ٥","segs":[["matn","﴿لَا يُسْأَلُ عَمَّا يَفْعَلُ وَهُمْ يُسْأَلُونَ﴾ فَمَنْ سَأَلَ: لِمَ فَعَلَ؟ فَقَدْ رَدَّ حُكْمَ الْكِتَابِ، وَمَنْ رَدَّ حُكْمَ الْكِتَابِ، كَانَ مِنَ الْكَافِرِينَ."]]},{"id":"ta8_6","label":"القدر · ٦","segs":[["matn","فَهَذَا جُمْلَةُ مَا يَحْتَاجُ إِلَيْهِ مَنْ هُوَ مُنَوَّرٌ قَلْبُهُ مِنْ أَوْلِيَاءِ اللَّهِ تَعَالَى، وَهِيَ دَرَجَةُ الرَّاسِخِينَ فِي الْعِلْمِ، لِأَنَّ الْعِلْمَ عِلْمَانِ: عِلْمٌ فِي الْخَلْقِ مَوْجُودٌ، وَعِلْمٌ فِي الْخَلْقِ مَفْقُودٌ،"]]},{"id":"ta8_7","label":"القدر · ٧","segs":[["matn","فَإِنْكَارُ الْعِلْمِ الْمَوْجُودِ كُفْرٌ، وَادِّعَاءُ الْعِلْمِ الْمَفْقُودِ كُفْرٌ، وَلَا يَثْبُتُ الْإِيمَانُ إِلَّا بِقَبُولِ الْعِلْمِ الْمَوْجُودِ، وَتَرْكِ طَلَبِ الْعِلْمِ الْمَفْقُودِ."]]},{"id":"ta8_8","label":"القدر · ٨","segs":[["matn","وَنُؤْمِنُ بِاللَّوْحِ وَالْقَلَمِ، وَبِجَمِيعِ مَا فِيهِ قَدْ رُقِمَ فَلَوِ اجْتَمَعَ الْخَلْقُ كُلُّهُمْ عَلَى شَيْءٍ كَتَبَهُ اللَّهُ تَعَالَى فِيهِ أَنَّهُ كَائِنٌ، لِيَجْعَلُوهُ غَيْرَ كَائِنٍ لَمْ يَقْدِرُوا عَلَيْهِ."]]},{"id":"ta8_9","label":"القدر · ٩","segs":[["matn","وَلَوِ اجْتَمَعُوا كُلُّهُمْ عَلَى شَيْءٍ لَمْ يَكْتُبْهُ اللَّهُ تَعَالَى فِيهِ، لِيَجْعَلُوهُ كَائِنًا لَمْ يَقْدِرُوا عَلَيْهِ. جَفَّ الْقَلَمُ بِمَا هُوَ كَائِنٌ إِلَى يَوْمِ الْقِيَامَةِ وَمَا أَخْطَأَ الْعَبْدَ لَمْ يَكُنْ لِيُصِيبَهُ، وَمَا أَصَابَهُ لَمْ يَكُنْ لِيُخْطِئَهُ."]]},{"id":"ta8_10","label":"القدر · ١٠","segs":[["matn","وَعَلَى الْعَبْدِ أَنْ يَعْلَمَ أَنَّ اللَّهَ قَدْ سَبَقَ عِلْمُهُ فِي كُلِّ كَائِنٍ مِنْ خَلْقِهِ، فَقَدَّرَ ذَلِكَ تَقْدِيرًا مُحْكَمًا مُبْرَمًا، لَيْسَ فِيهِ نَاقِضٌ،"]]},{"id":"ta8_11","label":"القدر · ١١","segs":[["matn","وَلَا مُعَقِّبٌ وَلَا مُزِيلٌ وَلَا مُغَيِّرٌ وَلَا نَاقِصٌ وَلَا زَائِدٌ مِنْ خَلْقِهِ فِي سَمَاوَاتِهِ وَأَرْضِهِ وَذَلِكَ مِنْ عَقْدِ الْإِيمَانِ وَأُصُولِ الْمَعْرِفَةِ وَالِاعْتِرَافِ بِتَوْحِيدِ اللَّهِ تَعَالَى وَرُبُوبِيَّتِهِ،"]]},{"id":"ta8_12","label":"القدر · ١٢","segs":[["matn","كَمَا قَالَ تَعَالَى فِي كِتَابِهِ: ﴿وَخَلَقَ كُلَّ شَيْءٍ فَقَدَّرَهُ تَقْدِيرًا﴾ وَقَالَ تَعَالَى: ﴿وَكَانَ أَمْرُ اللَّهِ قَدَرًا مَقْدُورًا﴾ فَوَيْلٌ لِمَنْ صَارَ لِلَّهِ تَعَالَى فِي الْقَدَرِ خَصِيمًا،"]]},{"id":"ta8_13","label":"القدر · ١٣","segs":[["matn","وَأَحْضَرَ لِلنَّظَرِ فِيهِ قَلْبًا سَقِيمًا لَقَدِ الْتَمَسَ بِوَهْمِهِ فِي فَحْصِ الْغَيْبِ سِرًّا كَتِيمًا، وَعَادَ بِمَا قَالَ فِيهِ أَفَّاكًا أَثِيمًا."]]}]},{"id":"ta9","title":"العرش والكرسي والإيمان بالملائكة والكتب","units":[{"id":"ta9_1","label":"العرش والكرسي والإيمان بالملائكة والكتب · ١","segs":[["matn","وَالْعَرْشُ وَالْكُرْسِيُّ حَقٌّ. وَهُوَ مُسْتَغْنٍ عَنِ الْعَرْشِ وَمَا دُونَهُ."]]},{"id":"ta9_2","label":"العرش والكرسي والإيمان بالملائكة والكتب · ٢","segs":[["matn","مُحِيطٌ بِكُلِّ شَيْءٍ وَفَوْقَهُ وَقَدْ أَعْجَزَ عَنِ الْإِحَاطَةِ خَلْقَهُ."]]},{"id":"ta9_3","label":"العرش والكرسي والإيمان بالملائكة والكتب · ٣","segs":[["matn","وَنَقُولُ: إِنَّ اللَّهَ اتَّخَذَ إِبْرَاهِيمَ خَلِيلًا، وَكَلَّمَ اللَّهُ مُوسَى تَكْلِيمًا، إِيمَانًا وَتَصْدِيقًا وَتَسْلِيمًا."]]},{"id":"ta9_4","label":"العرش والكرسي والإيمان بالملائكة والكتب · ٤","segs":[["matn","وَنُؤْمِنُ بِالْمَلَائِكَةِ وَالنَّبِيِّينَ، وَالْكُتُبِ الْمُنَزَّلَةِ عَلَى الْمُرْسَلِينَ، وَنَشْهَدُ أَنَّهُمْ كَانُوا عَلَى الْحَقِّ الْمُبِينِ."]]}]},{"id":"ta10","title":"أهل القبلة","units":[{"id":"ta10_1","label":"أهل القبلة · ١","segs":[["matn","وَنُسَمِّي أَهْلَ قِبْلَتِنَا مُسْلِمِينَ مُؤْمِنِينَ، مَا دَامُوا بِمَا جَاءَ بِهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُعْتَرِفِينَ، وَلَهُ بِكُلِّ مَا قَالَهُ وَأَخْبَرَ مُصَدِّقِينَ."]]},{"id":"ta10_2","label":"أهل القبلة · ٢","segs":[["matn","وَلَا نَخُوضُ فِي اللَّهِ، وَلَا نُمَارِي فِي دِينِ اللَّهِ."]]},{"id":"ta10_3","label":"أهل القبلة · ٣","segs":[["matn","وَلَا نُجَادِلُ فِي الْقُرْآنِ، وَنَشْهَدُ أَنَّهُ كَلَامُ رَبِّ الْعَالَمِينَ، نَزَلَ بِهِ الرُّوحُ الْأَمِينُ، فَعَلَّمَهُ سَيِّدَ الْمُرْسَلِينَ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَهُوَ كَلَامُ اللَّهِ تَعَالَى، لَا يُسَاوِيهِ شَيْءٌ مِنْ كَلَامِ الْمَخْلُوقِينَ، وَلَا نَقُولُ بِخَلْقِهِ، وَلَا نُخَالِفُ جَمَاعَةَ الْمُسْلِمِينَ."]]},{"id":"ta10_4","label":"أهل القبلة · ٤","segs":[["matn","وَلَا نُكَفِّرُ أَحَدًا مِنْ أَهْلِ الْقِبْلَةِ بِذَنْبٍ مَا لَمْ يَسْتَحِلَّهُ."]]},{"id":"ta10_5","label":"أهل القبلة · ٥","segs":[["matn","وَلَا نَقُولُ لَا يَضُرُّ مَعَ الْإِيمَانِ ذَنْبٌ لِمَنْ عَمِلَهُ."]]},{"id":"ta10_6","label":"أهل القبلة · ٦","segs":[["matn","وَنَرْجُو لِلْمُحْسِنِينَ مِنَ الْمُؤْمِنِينَ أَنْ يَعْفُوَ عَنْهُمْ وَيُدْخِلَهُمُ الْجَنَّةَ بِرَحْمَتِهِ، وَلَا نَأْمَنُ عَلَيْهِمْ، وَلَا نَشْهَدُ لَهُمْ بِالْجَنَّةِ، وَنَسْتَغْفِرُ لِمُسِيئِهِمْ وَنَخَافُ عَلَيْهِمْ، وَلَا نُقَنِّطُهُمْ."]]},{"id":"ta10_7","label":"أهل القبلة · ٧","segs":[["matn","وَالْأَمْنُ وَالْإِيَاسُ يَنْقُلَانِ عَنْ مِلَّةِ الْإِسْلَامِ، وَسَبِيلُ الْحَقِّ بَيْنَهُمَا لِأَهْلِ الْقِبْلَةِ."]]}]},{"id":"ta11","title":"الإيمان","units":[{"id":"ta11_1","label":"الإيمان · ١","segs":[["matn","وَلَا يَخْرُجُ الْعَبْدُ مِنَ الْإِيمَانِ إِلَّا بِجُحُودِ مَا أَدْخَلَهُ فِيهِ."]]},{"id":"ta11_2","label":"الإيمان · ٢","segs":[["matn","وَالْإِيمَانُ: هُوَ الْإِقْرَارُ بِاللِّسَانِ، وَالتَّصْدِيقُ بِالْجَنَانِ."]]},{"id":"ta11_3","label":"الإيمان · ٣","segs":[["matn","وَجَمِيعُ مَا صَحَّ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الشَّرْعِ وَالْبَيَانِ كُلُّهُ حَقٌّ."]]},{"id":"ta11_4","label":"الإيمان · ٤","segs":[["matn","وَالْإِيمَانُ وَاحِدٌ، وَأَهْلُهُ فِي أَصْلِهِ سَوَاءٌ وَالتَّفَاضُلُ بَيْنَهُمْ بِالْخَشْيَةِ وَالتُّقَى وَمُخَالَفَةِ الْهَوَى وَمُلَازَمَةِ الْأَوْلَى."]]},{"id":"ta11_5","label":"الإيمان · ٥","segs":[["matn","وَالْمُؤْمِنُونَ كُلُّهُمْ أَوْلِيَاءُ الرَّحْمَنِ وَأَكْرَمُهُمْ عِنْدَ اللَّهِ أَطْوَعُهُمْ وَأَتْبَعُهُمْ لِلْقُرْآنِ."]]},{"id":"ta11_6","label":"الإيمان · ٦","segs":[["matn","وَالْإِيمَانُ: هُوَ الْإِيمَانُ بِاللَّهِ، وَمَلَائِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْيَوْمِ الْآخِرِ، وَالْقَدَرِ، خَيْرِهِ وَشَرِّهِ، وَحُلْوِهِ وَمُرِّهِ، مِنَ اللَّهِ تَعَالَى."]]},{"id":"ta11_7","label":"الإيمان · ٧","segs":[["matn","وَنَحْنُ مُؤْمِنُونَ بِذَلِكَ كُلِّهِ، لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ، وَنُصَدِّقُهُمْ كُلَّهُمْ عَلَى مَا جَاؤُوا بِهِ."]]}]},{"id":"ta12","title":"أهل الكبائر","units":[{"id":"ta12_1","label":"أهل الكبائر · ١","segs":[["matn","وَأَهْلُ الْكَبَائِرِ مِنْ أُمَّةِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي النَّارِ لَا يُخَلَّدُونَ، إِذَا مَاتُوا وَهُمْ مُوَحِّدُونَ، وَإِنْ لَمْ يَكُونُوا تَائِبِينَ، بَعْدَ أَنْ لَقُوا اللَّهَ عَارِفِينَ. وَهُمْ فِي مَشِيئَتِهِ وَحُكْمِهِ،"]]},{"id":"ta12_2","label":"أهل الكبائر · ٢","segs":[["matn","إِنْ شَاءَ غَفَرَ لَهُمْ وَعَفَا عَنْهُمْ بِفَضْلِهِ، كَمَا ذَكَرَ عَزَّ وَجَلَّ فِي كِتَابِهِ: ﴿وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ﴾ وَإِنْ شَاءَ عَذَّبَهُمْ فِي النَّارِ بِعَدْلِهِ،"]]},{"id":"ta12_3","label":"أهل الكبائر · ٣","segs":[["matn","ثُمَّ يُخْرِجُهُمْ مِنْهَا بِرَحْمَتِهِ وَشَفَاعَةِ الشَّافِعِينَ مِنْ أَهْلِ طَاعَتِهِ، ثُمَّ يَبْعَثُهُمْ إِلَى جَنَّتِهِ. وَذَلِكَ بِأَنَّ اللَّهَ تَعَالَى تَوَلَّى أَهْلَ مَعْرِفَتِهِ، وَلَمْ يَجْعَلْهُمْ فِي الدَّارَيْنِ كَأَهْلِ نَكَرَتِهِ، الَّذِينَ خَابُوا مِنْ هِدَايَتِهِ،"]]},{"id":"ta12_4","label":"أهل الكبائر · ٤","segs":[["matn","وَلَمْ يَنَالُوا مِنْ وِلَايَتِهِ. اللَّهُمَّ يَا وَلِيَّ الْإِسْلَامِ وَأَهْلِهِ، ثَبِّتْنَا عَلَى الْإِسْلَامِ حَتَّى نَلْقَاكَ بِهِ."]]}]},{"id":"ta13","title":"الصلاة والجماعة وولاة الأمر","units":[{"id":"ta13_1","label":"الصلاة والجماعة وولاة الأمر · ١","segs":[["matn","وَنَرَى الصَّلَاةَ خَلْفَ كُلِّ بَرٍّ وَفَاجِرٍ مِنْ أَهْلِ الْقِبْلَةِ، وَعَلَى مَنْ مَاتَ مِنْهُمْ."]]},{"id":"ta13_2","label":"الصلاة والجماعة وولاة الأمر · ٢","segs":[["matn","وَلَا نُنْزِلُ أَحَدًا مِنْهُمْ جَنَّةً وَلَا نَارًا وَلَا نَشْهَدُ عَلَيْهِمْ بِكُفْرٍ وَلَا بِشِرْكٍ وَلَا بِنِفَاقٍ، مَا لَمْ يَظْهَرْ مِنْهُمْ شَيْءٌ مِنْ ذَلِكَ، وَنَذَرُ سَرَائِرَهُمْ إِلَى اللَّهِ تَعَالَى."]]},{"id":"ta13_3","label":"الصلاة والجماعة وولاة الأمر · ٣","segs":[["matn","وَلَا نَرَى السَّيْفَ عَلَى أَحَدٍ مِنْ أُمَّةِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَّا مَنْ وَجَبَ عَلَيْهِ السَّيْفُ."]]},{"id":"ta13_4","label":"الصلاة والجماعة وولاة الأمر · ٤","segs":[["matn","وَلَا نَرَى الْخُرُوجَ عَلَى أَئِمَّتِنَا وَوُلَاةِ أُمُورِنَا، وَإِنْ جَارُوا، وَلَا نَدْعُو عَلَيْهِمْ، وَلَا نَنْزِعُ يَدًا مِنْ طَاعَتِهِمْ، وَنَرَى طَاعَتَهُمْ مِنْ طَاعَةِ اللَّهِ عَزَّ وَجَلَّ فَرِيضَةً، مَا لَمْ يَأْمُرُوا بِمَعْصِيَةٍ، وَنَدْعُو لَهُمْ بِالصَّلَاحِ وَالْمُعَافَاةِ."]]},{"id":"ta13_5","label":"الصلاة والجماعة وولاة الأمر · ٥","segs":[["matn","وَنَتَّبِعُ السُّنَّةَ وَالْجَمَاعَةَ وَنَجْتَنِبُ الشُّذُوذَ وَالْخِلَافَ وَالْفُرْقَةَ."]]},{"id":"ta13_6","label":"الصلاة والجماعة وولاة الأمر · ٦","segs":[["matn","وَنُحِبُّ أَهْلَ الْعَدْلِ وَالْأَمَانَةِ وَنُبْغِضُ أَهْلَ الْجَوْرِ وَالْخِيَانَةِ."]]},{"id":"ta13_7","label":"الصلاة والجماعة وولاة الأمر · ٧","segs":[["matn","وَنَقُولُ: اللَّهُ أَعْلَمُ، فِيمَا اشْتَبَهَ عَلَيْنَا عِلْمُهُ."]]},{"id":"ta13_8","label":"الصلاة والجماعة وولاة الأمر · ٨","segs":[["matn","وَنَرَى الْمَسْحَ عَلَى الْخُفَّيْنِ، فِي السَّفَرِ وَالْحَضَرِ، كَمَا جَاءَ فِي الْأَثَرِ."]]},{"id":"ta13_9","label":"الصلاة والجماعة وولاة الأمر · ٩","segs":[["matn","وَالْحَجُّ وَالْجِهَادُ مَاضِيَانِ مَعَ أُولِي الْأَمْرِ مِنَ الْمُسْلِمِينَ، بَرِّهِمْ وَفَاجِرِهِمْ، إِلَى قِيَامِ السَّاعَةِ، لَا يُبْطِلُهُمَا شَيْءٌ وَلَا يَنْقُضُهُمَا."]]}]},{"id":"ta14","title":"الملائكة والقبر واليوم الآخر","units":[{"id":"ta14_1","label":"الملائكة والقبر واليوم الآخر · ١","segs":[["matn","وَنُؤْمِنُ بِالْكِرَامِ الْكَاتِبِينَ، فَإِنَّ اللَّهَ قَدْ جَعَلَهُمْ عَلَيْنَا حَافِظِينَ."]]},{"id":"ta14_2","label":"الملائكة والقبر واليوم الآخر · ٢","segs":[["matn","وَنُؤْمِنُ بِمَلَكِ الْمَوْتِ، الْمُوَكَّلِ بِقَبْضِ أَرْوَاحِ الْعَالَمِينَ."]]},{"id":"ta14_3","label":"الملائكة والقبر واليوم الآخر · ٣","segs":[["matn","وَبِعَذَابِ الْقَبْرِ لِمَنْ كَانَ لَهُ أَهْلًا، وَسُؤَالِ مُنْكَرٍ وَنَكِيرٍ فِي قَبْرِهِ عَنْ رَبِّهِ وَدِينِهِ وَنَبِيِّهِ، عَلَى مَا جَاءَتْ بِهِ الْأَخْبَارُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَنِ الصَّحَابَةِ رِضْوَانُ اللَّهِ عَلَيْهِمْ."]]},{"id":"ta14_4","label":"الملائكة والقبر واليوم الآخر · ٤","segs":[["matn","وَالْقَبْرُ رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ، أَوْ حُفْرَةٌ مِنْ حُفَرِ النِّيرَانِ."]]},{"id":"ta14_5","label":"الملائكة والقبر واليوم الآخر · ٥","segs":[["matn","وَنُؤْمِنُ بِالْبَعْثِ وَجَزَاءِ الْأَعْمَالِ يَوْمَ الْقِيَامَةِ، وَالْعَرْضِ وَالْحِسَابِ، وَقِرَاءَةِ الْكِتَابِ، وَالثَّوَابِ وَالْعِقَابِ وَالصِّرَاطِ وَالْمِيزَانِ."]]},{"id":"ta14_6","label":"الملائكة والقبر واليوم الآخر · ٦","segs":[["matn","وَالْجَنَّةُ وَالنَّارُ مَخْلُوقَتَانِ، لَا تَفْنَيَانِ أَبَدًا وَلَا تَبِيدَانِ وَأَنَّ اللَّهَ تَعَالَى خَلَقَ الْجَنَّةَ وَالنَّارَ قَبْلَ الْخَلْقِ، وَخَلَقَ لَهُمَا أَهْلًا، فَمَنْ شَاءَ مِنْهُمْ إِلَى الْجَنَّةِ فَضْلًا مِنْهُ، وَمَنْ شَاءَ مِنْهُمْ إِلَى النَّارِ عَدْلًا مِنْهُ، وَكُلٌّ يَعْمَلُ لِمَا قَدْ فُرِغَ لَهُ، وَصَائِرٌ إِلَى مَا خُلِقَ لَهُ. وَالْخَيْرُ وَالشَّرُّ مُقَدَّرَانِ عَلَى الْعِبَادِ."]]}]},{"id":"ta15","title":"الاستطاعة وأفعال العباد","units":[{"id":"ta15_1","label":"الاستطاعة وأفعال العباد · ١","segs":[["matn","وَالِاسْتِطَاعَةُ الَّتِي يَجِبُ بِهَا الْفِعْلُ، مِنْ نَحْوِ التَّوْفِيقِ الَّذِي لَا يَجُوزُ أَنْ يُوصَفَ الْمَخْلُوقُ بِهِ فَهِيَ مَعَ الْفِعْلِ. وَأَمَّا الِاسْتِطَاعَةُ مِنْ جِهَةِ الصِّحَّةِ وَالْوُسْعِ، وَالتَّمَكُّنِ وَسَلَامَةِ الْآلَاتِ فَهِيَ قَبْلَ الْفِعْلِ، وَبِهَا يَتَعَلَّقُ الْخِطَابُ، وَهُوَ كَمَا قَالَ تَعَالَى: ﴿لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا﴾."]]},{"id":"ta15_2","label":"الاستطاعة وأفعال العباد · ٢","segs":[["matn","وَأَفْعَالُ الْعِبَادِ خَلْقُ اللَّهِ وَكَسْبٌ مِنَ الْعِبَادِ."]]},{"id":"ta15_3","label":"الاستطاعة وأفعال العباد · ٣","segs":[["matn","وَلَمْ يُكَلِّفْهُمُ اللَّهُ تَعَالَى إِلَّا مَا يُطِيقُونَ، وَلَا يُطِيقُونَ إِلَّا مَا كَلَّفَهُمْ. وَهُوَ تَفْسِيرُ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، نَقُولُ: لَا حِيلَةَ لِأَحَدٍ، وَلَا حَرَكَةَ لِأَحَدٍ،"]]},{"id":"ta15_4","label":"الاستطاعة وأفعال العباد · ٤","segs":[["matn","وَلَا تَحَوُّلَ لِأَحَدٍ عَنْ مَعْصِيَةِ اللَّهِ، إِلَّا بِمَعُونَةِ اللَّهِ، وَلَا قُوَّةَ لِأَحَدٍ عَلَى إِقَامَةِ طَاعَةِ اللَّهِ وَالثَّبَاتِ عَلَيْهَا إِلَّا بِتَوْفِيقِ اللَّهِ."]]},{"id":"ta15_5","label":"الاستطاعة وأفعال العباد · ٥","segs":[["matn","وَكُلُّ شَيْءٍ يَجْرِي بِمَشِيئَةِ اللَّهِ تَعَالَى وَعِلْمِهِ وَقَضَائِهِ وَقَدَرِهِ. غَلَبَتْ مَشِيئَتُهُ الْمَشِيئَاتِ كُلَّهَا، وَغَلَبَ قَضَاؤُهُ الْحِيَلَ كُلَّهَا. يَفْعَلُ مَا يَشَاءُ وَهُوَ غَيْرُ ظَالِمٍ أَبَدًا. ﴿لَا يُسْأَلُ عَمَّا يَفْعَلُ وَهُمْ يُسْأَلُونَ﴾."]]}]},{"id":"ta16","title":"الدعاء وانتفاع الأموات","units":[{"id":"ta16_1","label":"الدعاء وانتفاع الأموات · ١","segs":[["matn","وَفِي دُعَاءِ الْأَحْيَاءِ وَصَدَقَاتِهِمْ مَنْفَعَةٌ لِلْأَمْوَاتِ."]]},{"id":"ta16_2","label":"الدعاء وانتفاع الأموات · ٢","segs":[["matn","وَاللَّهُ تَعَالَى يَسْتَجِيبُ الدَّعَوَاتِ، وَيَقْضِي الْحَاجَاتِ."]]},{"id":"ta16_3","label":"الدعاء وانتفاع الأموات · ٣","segs":[["matn","وَيَمْلِكُ كُلَّ شَيْءٍ وَلَا يَمْلِكُهُ شَيْءٌ وَلَا غِنَى عَنِ اللَّهِ تَعَالَى طَرْفَةَ عَيْنٍ، وَمَنِ اسْتَغْنَى عَنِ اللَّهِ طَرْفَةَ عَيْنٍ، فَقَدْ كَفَرَ وَصَارَ مِنْ أَهْلِ الْحَيْنِ."]]},{"id":"ta16_4","label":"الدعاء وانتفاع الأموات · ٤","segs":[["matn","وَاللَّهُ يَغْضَبُ وَيَرْضَى، لَا كَأَحَدٍ مِنَ الْوَرَى."]]}]},{"id":"ta17","title":"الصحابة والخلافة","units":[{"id":"ta17_1","label":"الصحابة والخلافة · ١","segs":[["matn","وَنُحِبُّ أَصْحَابَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَا نُفَرِّطُ فِي حُبِّ أَحَدٍ مِنْهُمْ، وَلَا نَتَبَرَّأُ مِنْ أَحَدٍ مِنْهُمْ. وَنُبْغِضُ مَنْ يُبْغِضُهُمْ، وَبِغَيْرِ الْخَيْرِ يَذْكُرُهُمْ. وَلَا نَذْكُرُهُمْ إِلَّا بِخَيْرٍ. وَحُبُّهُمْ دِينٌ وَإِيمَانٌ وَإِحْسَانٌ، وَبُغْضُهُمْ كُفْرٌ وَنِفَاقٌ وَطُغْيَانٌ."]]},{"id":"ta17_2","label":"الصحابة والخلافة · ٢","segs":[["matn","وَنُثْبِتُ الْخِلَافَةَ بَعْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوَّلًا لِأَبِي بَكْرٍ الصِّدِّيقِ رَضِيَ اللَّهُ عَنْهُ،"]]},{"id":"ta17_3","label":"الصحابة والخلافة · ٣","segs":[["matn","تَفْضِيلًا لَهُ وَتَقْدِيمًا عَلَى جَمِيعِ الْأُمَّةِ ثُمَّ لِعُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ ثُمَّ لِعُثْمَانَ رَضِيَ اللَّهُ عَنْهُ ثُمَّ لِعَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ وَهُمُ الْخُلَفَاءُ الرَّاشِدُونَ، وَالْأَئِمَّةُ الْمَهْدِيُّونَ."]]},{"id":"ta17_4","label":"الصحابة والخلافة · ٤","segs":[["matn","وَأَنَّ الْعَشَرَةَ الَّذِينَ سَمَّاهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَبَشَّرَهُمْ بِالْجَنَّةِ، نَشْهَدُ لَهُمْ بِالْجَنَّةِ، عَلَى مَا شَهِدَ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَوْلُهُ الْحَقُّ وَهُمْ: أَبُو بَكْرٍ،"]]},{"id":"ta17_5","label":"الصحابة والخلافة · ٥","segs":[["matn","وَعُمَرُ، وَعُثْمَانُ وَعَلِيٌّ، وَطَلْحَةُ، وَالزُّبَيْرُ، وَسَعْدٌ، وَسَعِيدٌ، وَعَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ، وَأَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ، وَهُوَ أَمِينُ هَذِهِ الْأُمَّةِ، رَضِيَ اللَّهُ عَنْهُمْ أَجْمَعِينَ."]]},{"id":"ta17_6","label":"الصحابة والخلافة · ٦","segs":[["matn","وَمَنْ أَحْسَنَ الْقَوْلَ فِي أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَزْوَاجِهِ الطَّاهِرَاتِ مِنْ كُلِّ دَنَسٍ، وَذُرِّيَّاتِهِ الْمُقَدَّسِينَ مِنْ كُلِّ رِجْسٍ فَقَدْ بَرِئَ مِنَ النِّفَاقِ."]]}]},{"id":"ta18","title":"العلماء والأولياء","units":[{"id":"ta18_1","label":"العلماء والأولياء · ١","segs":[["matn","وَعُلَمَاءُ السَّلَفِ مِنَ السَّابِقِينَ، وَمَنْ بَعْدَهُمْ مِنَ التَّابِعِينَ أَهْلِ الْخَيْرِ وَالْأَثَرِ، وَأَهْلِ الْفِقْهِ وَالنَّظَرِ لَا يُذْكَرُونَ إِلَّا بِالْجَمِيلِ، وَمَنْ ذَكَرَهُمْ بِسُوءٍ فَهُوَ عَلَى غَيْرِ السَّبِيلِ."]]},{"id":"ta18_2","label":"العلماء والأولياء · ٢","segs":[["matn","وَلَا نُفَضِّلُ أَحَدًا مِنَ الْأَوْلِيَاءِ عَلَى أَحَدٍ مِنَ الْأَنْبِيَاءِ عَلَيْهِمُ السَّلَامُ، وَنَقُولُ: نَبِيٌّ وَاحِدٌ أَفْضَلُ مِنْ جَمِيعِ الْأَوْلِيَاءِ."]]},{"id":"ta18_3","label":"العلماء والأولياء · ٣","segs":[["matn","وَنُؤْمِنُ بِمَا جَاءَ مِنْ كَرَامَاتِهِمْ، وَصَحَّ عَنِ الثِّقَاتِ مِنْ رِوَايَاتِهِمْ."]]}]},{"id":"ta19","title":"أشراط الساعة","units":[{"id":"ta19_1","label":"أشراط الساعة · ١","segs":[["matn","وَنُؤْمِنُ بِأَشْرَاطِ السَّاعَةِ: مِنْ خُرُوجِ الدَّجَّالِ، وَنُزُولِ عِيسَى ابْنِ مَرْيَمَ عَلَيْهِ السَّلَامُ مِنَ السَّمَاءِ وَنُؤْمِنُ بِطُلُوعِ الشَّمْسِ مِنْ مَغْرِبِهَا، وَخُرُوجِ دَابَّةِ الْأَرْضِ مِنْ مَوْضِعِهَا."]]},{"id":"ta19_2","label":"أشراط الساعة · ٢","segs":[["matn","وَلَا نُصَدِّقُ كَاهِنًا وَلَا عَرَّافًا، وَلَا مَنْ يَدَّعِي شَيْئًا يُخَالِفُ الْكِتَابَ وَالسُّنَّةَ وَإِجْمَاعَ الْأُمَّةِ."]]},{"id":"ta19_3","label":"أشراط الساعة · ٣","segs":[["matn","وَنَرَى الْجَمَاعَةَ حَقًّا وَصَوَابًا، وَالْفُرْقَةَ زَيْغًا وَعَذَابًا."]]}]},{"id":"ta20","title":"دين الإسلام والخاتمة","units":[{"id":"ta20_1","label":"دين الإسلام والخاتمة · ١","segs":[["matn","وَدِينُ اللَّهِ فِي الْأَرْضِ وَالسَّمَاءِ وَاحِدٌ، وَهُوَ دِينُ الْإِسْلَامِ، قَالَ اللَّهُ تَعَالَى: ﴿إِنَّ الدِّينَ عِنْدَ اللَّهِ الْإِسْلَامُ﴾ وَقَالَ تَعَالَى: ﴿وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا﴾."]]},{"id":"ta20_2","label":"دين الإسلام والخاتمة · ٢","segs":[["matn","وَهُوَ بَيْنَ الْغُلُوِّ وَالتَّقْصِيرِ وَبَيْنَ التَّشْبِيهِ وَالتَّعْطِيلِ، وَبَيْنَ الْجَبْرِ وَالْقَدَرِ، وَبَيْنَ الْأَمْنِ وَالْإِيَاسِ."]]},{"id":"ta20_3","label":"دين الإسلام والخاتمة · ٣","segs":[["matn","فَهَذَا دِينُنَا وَاعْتِقَادُنَا ظَاهِرًا وَبَاطِنًا، وَنَحْنُ بَرَاءٌ إِلَى اللَّهِ مِنْ كُلِّ مَنْ خَالَفَ الَّذِي ذَكَرْنَاهُ وَبَيَّنَّاهُ، وَنَسْأَلُ اللَّهَ تَعَالَى أَنْ يُثَبِّتَنَا عَلَى الْإِيمَانِ، وَيَخْتِمَ لَنَا بِهِ، وَيَعْصِمَنَا مِنَ الْأَهْوَاءِ الْمُخْتَلِفَةِ،"]]},{"id":"ta20_4","label":"دين الإسلام والخاتمة · ٤","segs":[["matn","وَالْآرَاءِ الْمُتَفَرِّقَةِ، وَالْمَذَاهِبِ الرَّدِيَّةِ، مِثْلِ الْمُشَبِّهَةِ، وَالْمُعْتَزِلَةِ، وَالْجَهْمِيَّةِ، وَالْجَبْرِيَّةِ، وَالْقَدَرِيَّةِ، وَغَيْرِهِمْ، مِنَ الَّذِينَ خَالَفُوا السُّنَّةَ وَالْجَمَاعَةَ وَحَالَفُوا الضَّلَالَةَ، وَنَحْنُ مِنْهُمْ بَرَاءٌ وَهُمْ عِنْدَنَا ضُلَّالٌ وَأَرْدِيَاءُ وَبِاللَّهِ الْعِصْمَةُ وَالتَّوْفِيقُ."]]}]}],"basmala":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ","sharh":false};
